 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    q = (x+dx, y+dy)
                    if 0 <= q[0] < h and 0 <= q[1] < w and q not in seen and grid[q[0]][q[1]] == color:
                        seen.add(q)
                        stack.append(q)
            comps.append((color, cells))
    def shape(cells):
        mr = min(r for r, c in cells)
        mc = min(c for r, c in cells)
        return frozenset((r-mr, c-mc) for r,c in cells)
    palette = {}
    for color, cells in comps:
        if color != 1:
            palette.setdefault(shape(cells), color)
    out = [row[:] for row in grid]
    for color, cells in comps:
        if color == 1:
            new_color = palette.get(shape(cells))
            if new_color is not None:
                for r,c in cells:
                    out[r][c] = new_color
    return out
